// dsh-context-compress —— 上下文压缩（软滑动）
//
// 只管"会话之内"：
//   1. 每轮把前情提要 digest 注入系统提示
//   2. 每 N 轮请求她把前情压回 digest（覆盖写）
//
// 不管交接、不管资产清单 —— 那是 dsh-session-rotate 的活。
// 只装这一个也能用：会话内注意力不散，只是换会话时没有交接。
//
// 不删历史（DSH 没有裁剪 API，agent/request 也不许改 messages）。
// 注入通道：ctx.systemPrompt.section().text 每个模型步重新求值。
//
// 2026-10-27：轮次和"上次请求压缩的轮次"落盘（context-compress-state.json），
// 以前只在内存里，DSH 一重启就归零、同一轮反复请求。
import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import z from '@deepseek-ai/schemastery';
import { createUpdateChecker } from './update-check.js';

export const name = 'dsh-context-compress';
export const inject = ['systemPrompt'];

const pkgVersion = (() => {
  try {
    return JSON.parse(fs.readFileSync(new URL('../package.json', import.meta.url), 'utf8')).version || '0.0.0';
  } catch {
    return '0.0.0';
  }
})();

export const Config = z.object({
  enabled: z.boolean().default(true).description('总开关'),
  digestPath: z.string().default('').description('digest 文件路径，留空 = <DSH_HOME>/context-digest.md'),
  everyTurns: z.natural().default(30).description('每多少轮请求一次压缩'),
  maxDigestChars: z.natural().default(4000).description('digest 最多注入多少字'),
  sectionOrder: z.natural().default(9400).description('system prompt 排序'),
  updateCheck: z.boolean().default(true).description('每天检查一次 npm 上有没有新版本（只提示，不自动安装）'),
});

function log(msg) {
  try {
    const dir = path.join(process.env.DSH_HOME || path.join(os.homedir(), '.dsh'), 'logs');
    fs.mkdirSync(dir, { recursive: true });
    fs.appendFileSync(path.join(dir, 'context-compress.log'), `[${new Date().toISOString()}] ${msg}\n`);
  } catch {}
}

function sessionIdOf(session) {
  const direct = session?.id;
  if (typeof direct === 'string' && direct.length > 0) return direct;
  const fromHeader = session?.header?.id;
  return typeof fromHeader === 'string' && fromHeader.length > 0 ? fromHeader : '';
}

export function apply(ctx, config) {
  const cfg = {
    enabled: true,
    everyTurns: 30,
    maxDigestChars: 4000,
    sectionOrder: 9400,
    digestPath: '',
    updateCheck: true,
    ...(config || {}),
  };
  const dshHome = process.env.DSH_HOME || path.join(os.homedir(), '.dsh');
  const digestPath = cfg.digestPath || path.join(dshHome, 'context-digest.md');
  const statePath = path.join(dshHome, 'context-compress-state.json');

  const updateChecker = createUpdateChecker({
    npmName: 'dsh-context-compress',
    version: pkgVersion,
    log,
    enabled: cfg.updateCheck !== false,
  });
  const updateTimer = setTimeout(() => {
    updateChecker.check().catch(() => {});
  }, 15000);
  updateTimer.unref?.();

  const state = { sessionId: '', turns: 0, lastRequestTurn: 0, updatedAt: 0 };
  try {
    if (fs.existsSync(statePath)) Object.assign(state, JSON.parse(fs.readFileSync(statePath, 'utf8')) || {});
  } catch (e) {
    log('读状态失败（按 0 重新开始）：' + (e?.message ?? e));
  }

  let saveTimer = null;
  function save() {
    try {
      fs.mkdirSync(path.dirname(statePath), { recursive: true });
      const tmp = `${statePath}.tmp-${process.pid}`;
      state.updatedAt = Date.now();
      fs.writeFileSync(tmp, JSON.stringify(state), 'utf8');
      fs.renameSync(tmp, statePath);
    } catch (e) {
      log('写状态失败：' + (e?.message ?? e));
    }
  }
  function scheduleSave() {
    if (saveTimer) return;
    saveTimer = setTimeout(() => {
      saveTimer = null;
      save();
    }, 1000);
    saveTimer.unref?.();
  }

  // 2026-10-27：回调是 (session, event) 两个参数 —— 以前只写 (event)，
  // 拿到的是 session，`event.type` 永远 undefined，轮次从来没数过。
  try {
    ctx.on(
      'session/event',
      (session, event) => {
        try {
          const sid = sessionIdOf(session);
          if (sid && sid !== state.sessionId) {
            // 换会话：压缩节奏从这一轮重新算（digest 本身跨会话保留）。
            state.sessionId = sid;
            state.turns = 0;
            state.lastRequestTurn = 0;
            scheduleSave();
          }
          if (event && event.type === 'turn/end') {
            state.turns += 1;
            scheduleSave();
          }
        } catch (e) {
          log('处理会话事件失败：' + (e?.message ?? e));
        }
      },
      'dsh-context-compress: turns',
    );
  } catch (e) {
    log('订阅 session/event 失败：' + (e?.message ?? e));
  }

  try {
    ctx.systemPrompt.section({
      name: 'context-compress:digest',
      order: cfg.sectionOrder,
      text: () => {
        if (cfg.enabled === false) return '';
        const parts = [];

        // ① 前情提要
        try {
          if (fs.existsSync(digestPath)) {
            const text = fs.readFileSync(digestPath, 'utf8').trim();
            if (text) {
              const cut = text.length > cfg.maxDigestChars ? text.slice(0, cfg.maxDigestChars) + '…' : text;
              parts.push(`【前情提要（压缩过的，旧细节以这个为准）】\n${cut}`);
            }
          }
        } catch (e) {
          log('读 digest 失败：' + (e?.message ?? e));
        }

        // ② 定期请求压缩
        const since = state.turns - state.lastRequestTurn;
        if (state.turns > 0 && since >= cfg.everyTurns) {
          state.lastRequestTurn = state.turns;
          scheduleSave();
          parts.push(
            `【上下文压缩请求】已经聊了 ${state.turns} 轮，请把到目前为止的内容压进 ${digestPath}（直接覆盖写）。` +
              '只留六格：资产/能力（一行一项，只写有什么、怎么用一句话）、关系状态、最近发生、现在的偏好雷区、未完成、上次说到哪。' +
              '不要写过程细节、不要写小作文，压完继续正常回话。',
          );
          log(`请求压缩（第 ${state.turns} 轮）`);
        }
        return parts.join('\n\n');
      },
    });
    log(`已挂载：digest=${digestPath} 每 ${cfg.everyTurns} 轮请求一次`);
  } catch (e) {
    log('挂载 prompt section 失败：' + (e?.message ?? e));
  }
}
